<style>
	.tech-stack {
		width: 100%;
	}

	.tech-items {
		display: grid;
		grid-template-columns: repeat(4, minmax(0, 1fr));
		align-items: center;
		justify-items: center;
		gap: 2rem 1rem;
		padding: 2rem 1rem;
	}

	.tech-items :global(svg) {
		height: 60px;
		width: 60px;
		flex-shrink: 0;
		color: currentColor;
		transition:
			color 200ms ease,
			width 200ms ease,
			height 200ms ease;
	}

	.tech-items :global(svg rect) {
		fill: transparent !important;
	}

	.tech-items :global(svg path) {
		fill: currentColor !important;
	}

	.tech-items :global(svg path[fill='none']) {
		fill: none !important;
	}

	.tech-items :global(svg:hover path[fill='none']) {
		fill: none !important;
	}

	.tech-items :global(svg:hover) {
		color: #595f34;
	}

	@media (min-width: 768px) {
		.tech-items {
			grid-template-columns: repeat(8, minmax(0, 1fr));
		}
	}

	.tech-items :global(.svelte-logo g > path:first-child) {
		fill: currentColor !important;
	}

	.tech-items :global(.svelte-logo g > path:nth-child(2)) {
		fill: #d1c6ae !important;
	}

	.tech-items :global(.postgres-logo path) {
		fill: none !important;
		stroke: #fff !important;
	}

	.tech-items :global(.postgres-logo > rect) {
		fill: transparent !important;
	}

	.tech-items :global(.postgres-logo g > path:nth-of-type(1)) {
		fill: currentColor !important;
		stroke: none !important;
	}

	.tech-items :global(.postgres-logo g > path:nth-of-type(2)) {
		fill: none !important;
		stroke: currentColor !important;
	}

	.tech-items :global(.postgres-logo g > path:nth-of-type(3)) {
		fill: currentColor !important;
		stroke: none !important;
		opacity: 0.45;
	}

	.tech-items :global(.postgres-logo:hover g > path:nth-of-type(1)),
	.tech-items :global(.postgres-logo:hover g > path:nth-of-type(3)) {
		fill: #595f34 !important;
	}

	.tech-items :global(.postgres-logo:hover g > path:nth-of-type(2)) {
		stroke: #595f34 !important;
	}
</style>
